import sympy

N_HYP = 2
NEG_Q_INDEX = 2

CONDITION_LABELS = [
    'H_1: Let F_p(x) be the polynomial ring over the finite field with p elements',
    'H_2: Let I = (x^2 + 1) be the ideal generated by x^2 + 1',
    'not Q: The factor ring F_p(x)/I is a field if and only if p = 3 mod 4'
]

def conditions(witness):
    try:
        if isinstance(witness, (tuple, list)):
            p = int(witness[0])
        else:
            p = int(witness)
        h1 = p >= 2
    except Exception:
        h1 = False

    try:
        h2 = True
    except Exception:
        h2 = False

    try:
        if isinstance(witness, (tuple, list)):
            p = int(witness[0])
        else:
            p = int(witness)
            
        factors = sympy.factorint(p)
        is_prime_power = (len(factors) == 1)
        
        # F_p(x)/(x^2+1) is a field iff F_p is a field (p is a prime power)
        # and x^2+1 is irreducible over F_p (which happens iff p % 4 == 3).
        is_field = is_prime_power and (p % 4 == 3)
        
        # The conclusion states it is a field iff p = 3 mod 4
        conclusion = (is_field == (p % 4 == 3))
        
        neg_q = not conclusion
    except Exception:
        neg_q = False

    return [h1, h2, neg_q]